import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { useToast } from '@/hooks/use-toast';
import { loginUser } from '@/lib/auth';
import type { User } from '@/lib/types';

interface LoginPageProps {
  // onSuccess receives the minimal login response from the server
  onSuccess: (data: { role: 'parent' | 'child'; username: string }) => void;
}

export function LoginPage({ onSuccess }: LoginPageProps) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const { toast } = useToast();
  const router = useRouter();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    
    try {
        console.log('Attempting login');
        console.log(`Email: ${email}, Password: ${password}`);
  const data = await loginUser(email, password);
      
      toast({
        title: 'Success',
        description: 'Login successful!',
      });

      // server returns { success: true, role, username }
      const loginResult = { role: data.role as 'parent' | 'child', username: data.username };
      onSuccess(loginResult);

      // navigate to a role-specific page (creates a visible URL change)
      try {
        if (loginResult.role === 'parent') {
          router.push('/parent');
        } else {
          router.push('/child');
        }
      } catch (e) {
        // If router push fails, fall back to staying on the page (state already updated)
        console.error('Router navigation failed', e);
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Login failed',
        variant: 'destructive',
      });
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-b from-gray-900 to-gray-800">
      <Card className="p-8 w-full max-w-md bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
        <h1 className="text-3xl font-bold text-center mb-8">Welcome Back</h1>
        <form onSubmit={handleLogin} className="space-y-6">
          <div className="space-y-2">
            <label htmlFor="email" className="text-sm font-medium">
              Email
            </label>
            <Input
              id="email"
              type="email"
              placeholder="Enter your email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="w-full"
            />
          </div>
          <div className="space-y-2">
            <label htmlFor="password" className="text-sm font-medium">
              Password
            </label>
            <Input
              id="password"
              type="password"
              placeholder="Enter your password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="w-full"
            />
          </div>
          <Button type="submit" className="w-full">
            Log In
          </Button>
        </form>
      </Card>
    </div>
  );
}